SELECT
    FO.CHAVE_FOLHA,
    FF.COD_INSTITUCIONAL,
    PD.NOME_DIVISAO,
    PS.NOME_SITUACAO,
    FP.ID_FUNCIONARIO_PERFIL,
    FFP.ID_FUNCIONARIO_PERFIL,
    FFP.ID_FOLHA_PERFIL,
    FFP.DATA_FIM
FROM
    SW_FUNPREV.FOLHA FO
    JOIN SW_FUNPREV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    JOIN SW_FUNPREV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    JOIN SW_FUNPREV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_FUNPREV.FOLHA_FUNC_PERFIL FFP ON FFP.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
WHERE
    --FF.COD_INSTITUCIONAL IN ('359590-X', '368240-4', '399798-7')
    FF.COD_INSTITUCIONAL IN ('460044-4','458055-9','380650-2','460132-7','453067-5','459957-8','435864-3','396074-9','380247-7','460002-9','444178-8','380580-8','387974-7','460010-0','424325-X','453500-6','449634-5','460042-8','460151-3')
    AND FO.MES IN (9)
    AND FO.ANO = 2026
ORDER BY
    FO.ANO,
    FO.MES,
    FF.COD_INSTITUCIONAL;

